sysauto_script.script:
var grInvoice = new GlideRecord("x_sigh_a_a_portal_invoices");
// Holen des aktuellen Datums
var now = new GlideDateTime();

// Erster Tag des aktuellen Monats
var startDate = new GlideDateTime();
startDate.setValue(now.getYearUTC() + '-' + (now.getMonthLocalTime() + 0) + '-01 00:00:00'); // Erster Tag des Monats
//gs.info(startDate);
// Letzter Tag des aktuellen Monats
var endDate = new GlideDateTime();
endDate.setValue(now.getYearUTC() + '-' + (now.getMonthLocalTime() + 0) + '-' + startDate.getDaysInMonthLocalTime() + ' 23:59:59'); // Letzter Tag des Monats
//gs.info(endDate);
// Abfragen der Einträge für den aktuellen Monat
grInvoice.addQuery('date', '>=', startDate); // Ab dem ersten Tag des Monats
grInvoice.addQuery('date', '<=', endDate); // Bis zum letzten Tag des Monats
grInvoice.query();

var monthNames = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"
];

var Headers = ["Vermittler", "Buchungsart", "Zusatztext", "Betrag in €", "Fälligkeit"];
var fileName = 'Test.csv';
var csvData = '';
for (var i = 0; i < Headers.length; i++) {
    csvData = csvData + '"' + Headers[i] + '"' + ',';
}
csvData = csvData + "\r\n";

while (grInvoice.next()) {

    var vermittlerSysId = grInvoice.getValue('company'); //Geht auch leichter mit Dotwalking s.u.
    var userGR = new GlideRecord('core_company'); // Habs mal drinn gelassen um beide Wege zu zeigen
    if (userGR.get(vermittlerSysId)) {
        var vermittler = userGR.getValue('name');
    }
    var buchungsart = 'Belastung';
    //---------------------------------------------------
    ////Zusatztext als Beispiel hier der Monat der Invoices
    var date = grInvoice.getValue('date');
    var month = new GlideDateTime(date).getMonthLocalTime();
    var zusatztext = monthNames[month-1];
    //-------------------------------------------------------
    var kosten = grInvoice.getValue('netto_price');
    var faelligkeit = grInvoice.getValue('date');
    csvData = csvData + '"' + vermittler + '",' + '"' + buchungsart + '",' + '"' + zusatztext + '",' + '"' + kosten + '",' + '"' + faelligkeit + '"';
    csvData = csvData + "\r\n";
}

gs.info(csvData);

//attach the file to a record.
var recordSysId = '955fd65a1ba812503f86b9118b4bcb8c'; // Die sys_id des Ziel-Datensatzes
var grRec = new GlideRecord("sys_attachment"); // Ersetze mit dem tatsächlichen Tabellennamen

if (grRec.get(recordSysId)) { // Prüfen, ob der Datensatz existiert
    var grAttachment = new GlideSysAttachment();

    // Alle Attachments für den Datensatz abrufen und löschen
    var attachments = grAttachment.getAttachments(grRec);
    while (attachments.next()) {
        grAttachment.deleteAttachment(attachments.sys_id); // Jedes Attachment entfernen
    }

    // Neues Attachment hinzufügen
    var sysId = grAttachment.write(grRec, fileName, 'application/csv', csvData);

    gs.info('CSV-Datei erstellt und Event ausgelöst mit Attachment sys_id: ' + sysId);
    gs.eventQueue("x_sigh_a_a_portal.agency.asset_portal.em", grRec, "eins", sysId);
} else {
    gs.info('Datensatz mit sys_id ' + recordSysId + ' wurde nicht gefunden.');
}
//gs.eventQueue("x_sigh_a_a_portal.agency.asset_portal.em",null, "eins", 'sysId');
